{
  "root": "main_stack",
  "state": {
    "itineraryDays": [
      {
        "id": "day1",
        "dayTitle": "Day 1: Arashiyama Riverside",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a3/Arashiyama_Bamboo_Grove_Kyoto_Japan.jpg/1200px-Arashiyama_Bamboo_Grove_Kyoto_Japan.jpg",
        "imageAlt": "Arashiyama Bamboo Grove Kyoto Japan",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/tree.svg",
        "morning": "Walk through the Bamboo Grove and Tenryu-ji Zen Garden for early foliage.",
        "afternoon": "Relaxed boat ride on the Hozugawa River or Otagi Nenbutsu-ji visit.",
        "evening": "Vegetarian-friendly dining in the Arashiyama neighborhood.",
        "actionLabel": "Arashiyama Guide",
        "actionUrl": "https://www.japan-guide.com/e/e3912.html"
      },
      {
        "id": "day2",
        "dayTitle": "Day 2: Higashiyama Heritage",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/Kiyomizu-dera_in_Kyoto-r.jpg/1200px-Kiyomizu-dera_in_Kyoto-r.jpg",
        "imageAlt": "Kiyomizu-dera in Kyoto",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/building.svg",
        "morning": "Kiyomizu-dera Temple and the historic streets of Sannenzaka.",
        "afternoon": "Traditional tea ceremony experience at a local machiya.",
        "evening": "Explore Gion's alleys; try Yuba (tofu skin) specialties.",
        "actionLabel": "Tea Ceremony",
        "actionUrl": "https://www.tea-kyoto.com/"
      }
    ],
    "costBreakdown": [
      {
        "Day": "Day 1",
        "Meals": "$120",
        "Activities": "$60",
        "Transport": "$20",
        "Total": "$200"
      },
      {
        "Day": "Day 2",
        "Meals": "$140",
        "Activities": "$80",
        "Transport": "$15",
        "Total": "$235"
      },
      {
        "Day": "Day 3",
        "Meals": "$110",
        "Activities": "$50",
        "Transport": "$20",
        "Total": "$180"
      },
      {
        "Day": "Day 4",
        "Meals": "$130",
        "Activities": "$70",
        "Transport": "$15",
        "Total": "$215"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h1",
        "subtitle_h2",
        "itinerary_table",
        "dining_guide_card",
        "cost_breakdown_title",
        "cost_breakdown_table",
        "quick_actions_title",
        "quick_actions_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Relaxed Autumn Foliage Tour",
        "variant": "h1"
      },
      "children": []
    },
    "subtitle_h2": {
      "type": "Text",
      "props": {
        "text": "4-Day Culinary & Scenic Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "statePath": "/itineraryDays",
        "columns": [
          {
            "key": "dayTitle",
            "label": "Day"
          },
          {
            "key": "image",
            "label": "Image"
          },
          {
            "key": "imageAlt",
            "label": "Image Alt"
          },
          {
            "key": "icon",
            "label": "Icon"
          },
          {
            "key": "morning",
            "label": "Morning Activity"
          },
          {
            "key": "afternoon",
            "label": "Afternoon Activity"
          },
          {
            "key": "evening",
            "label": "Evening Activity"
          },
          {
            "key": "actionLabel",
            "label": "Action"
          },
          {
            "key": "actionUrl",
            "label": "URL"
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "dayTitle",
        "highlightColumns": [
          "morning",
          "afternoon",
          "evening"
        ]
      },
      "children": []
    },
    "dining_guide_card": {
      "type": "Card",
      "props": {},
      "children": [
        "dining_guide_title",
        "safe_dishes_title",
        "safe_dishes_list",
        "gf_areas_title",
        "gf_areas_list",
        "tip_title",
        "tip_text"
      ]
    },
    "dining_guide_title": {
      "type": "Text",
      "props": {
        "text": "Gluten-Friendly Dining Guide",
        "variant": "h3"
      },
      "children": []
    },
    "safe_dishes_title": {
      "type": "Text",
      "props": {
        "text": "Safe Dishes",
        "variant": "body"
      },
      "children": []
    },
    "safe_dishes_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "safe_dish_1",
        "safe_dish_2",
        "safe_dish_3"
      ]
    },
    "safe_dish_1": {
      "type": "Text",
      "props": {
        "text": "Sashimi (without soy sauce)"
      },
      "children": []
    },
    "safe_dish_2": {
      "type": "Text",
      "props": {
        "text": "Yuba (tofu skin)"
      },
      "children": []
    },
    "safe_dish_3": {
      "type": "Text",
      "props": {
        "text": "Salt-grilled fish (Shioyaki)"
      },
      "children": []
    },
    "gf_areas_title": {
      "type": "Text",
      "props": {
        "text": "Naturally GF Areas",
        "variant": "body"
      },
      "children": []
    },
    "gf_areas_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "gf_area_1",
        "gf_area_2"
      ]
    },
    "gf_area_1": {
      "type": "Text",
      "props": {
        "text": "Gion (Tofu specialists)"
      },
      "children": []
    },
    "gf_area_2": {
      "type": "Text",
      "props": {
        "text": "Nishiki Market (Fresh seafood/pickles)"
      },
      "children": []
    },
    "tip_title": {
      "type": "Text",
      "props": {
        "text": "Tip",
        "variant": "body"
      },
      "children": []
    },
    "tip_text": {
      "type": "Text",
      "props": {
        "text": "Always carry a Japanese \"Gluten Sensitivity Card\" to show chefs."
      },
      "children": []
    },
    "cost_breakdown_title": {
      "type": "Text",
      "props": {
        "text": "Daily Cost Breakdown (per Couple)",
        "variant": "h3"
      },
      "children": []
    },
    "cost_breakdown_table": {
      "type": "Table",
      "props": {
        "statePath": "/costBreakdown",
        "columns": [
          {
            "key": "Day",
            "label": "Day"
          },
          {
            "key": "Meals",
            "label": "Meals"
          },
          {
            "key": "Activities",
            "label": "Activities"
          },
          {
            "key": "Transport",
            "label": "Transport"
          },
          {
            "key": "Total",
            "label": "Total"
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table",
        "primaryColumn": "Day",
        "numericColumns": [
          "Meals",
          "Activities",
          "Transport",
          "Total"
        ]
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "kyoto_transit_button",
        "gf_dining_card_button"
      ]
    },
    "kyoto_transit_button": {
      "type": "Button",
      "props": {
        "label": "Kyoto Transit Map"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.city.kyoto.lg.jp/kotsu/category/166.html"
          }
        }
      },
      "children": []
    },
    "gf_dining_card_button": {
      "type": "Button",
      "props": {
        "label": "Gluten Sensitivity Card"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.celiactravel.com/cards/japanese/"
          }
        }
      },
      "children": []
    }
  }
}
